-- One in a Computer · accounts, profiles and saved results (Supabase / Postgres)
-- Generated by supabase/build-schema.js. Paste the whole file into Supabase → SQL editor → New query, and press Run.
-- It is safe to run again after an update: it only creates what is missing and replaces the functions.

-- ============ 1. The name filter: the same rules as namecheck.js ============
create or replace function public.name_banned_in(v text, w text, allow text[]) returns boolean
language plpgsql immutable set search_path = '' as $fn$
declare p int := 0; q int; off int; a text; covered boolean;
begin
  loop
    q := strpos(substr(v, p + 1), w); exit when q = 0; p := p + q;
    covered := false;
    foreach a in array allow loop
      continue when strpos(a, w) = 0;
      off := 0;
      loop
        q := strpos(substr(v, off + 1), a); exit when q = 0; q := off + q;
        if q <= p and q + length(a) >= p + length(w) then covered := true; exit; end if;
        off := q;
      end loop;
      exit when covered;
    end loop;
    if not covered then return true; end if;
  end loop;
  return false;
end $fn$;

-- null when the text is fine; 'bad' when it is inappropriate; 'reserved' when it pretends to be staff
create or replace function public.name_problem(n text) returns text
language plpgsql immutable set search_path = '' as $fn$
declare
  subs text[] := array['fuck','fuk','fck','shit','cunt','bitch','biatch','bastard','whore','slut','dick','cock','pussy','penis','vagina','dildo','porn','nude','boob','tits','titty','titties','anal','anus','jizz','wank','twat','prick','bollock','arse','piss','sex','horny','milf','rape','rapist','molest','pedophil','paedophil','nazi','hitler','kkk','nigg','negro','faggot','retard','tranny','kike','spic','chink','gook','wetback','coon','dyke','paki','raghead','towelhead','beaner','asshole','asswipe','asshat','assface','assclown','dumbass','jackass','fatass','kissmyass','bigass','cumshot','cumslut','killyourself','testicle','scrotum','erection','orgasm','semen','blowjob','handjob','rimjob','hentai','boner','butthole','buttplug','ballsack','ballsdeep','nutsack','onlyfans','pornhub','whitepower','siegheil','whitesupremac','killall','bendover','mikehunt','mikehawk','mikeoxlong','mikelitoris','hughjass','hughjanus','hughgrection','seymourbutts','seymorebutts','philmccrack','phillmccrack','amandahuggin','ivanaboner','jennytalia','dixienormous','heywoodja','admin','moderator','superuser','scipa','oneinacomputer']::text[];
  allow text[] := array['scunthorpe','dickens','dickinson','dickson','benedick','dickory','cockpit','peacock','hancock','hitchcock','cocktail','cockatoo','cockatiel','cockroach','cockney','cockerel','cocker','cockle','shuttlecock','woodcock','babcock','weathercock','gamecock','stopcock','analysis','analyse','analyze','analyst','analytic','analog','analects','canal','banal','analgesic','manuscript','janus','uranus','essex','sussex','middlesex','sextant','sexton','sextet','sextuple','sexagesimal','grape','drape','scrape','trapeze','therapeutic','therapist','parapet','rapeseed','skyscraper','scraper','draper','crape','nazir','nazim','nazia','nazif','spice','spicy','spick','despicable','conspicuous','auspicious','auspice','suspicion','suspicious','perspicacious','spicule','hospice','aspic','raccoon','cocoon','tycoon','puccoon','vandyke','pakistan','montenegro','negroni','niggle','niggling','snigger','sniggle','arsenal','arsenic','arsene','parse','sparse','coarse','hoarse','rehearse','marseille','pissarro','prickly','prickle','swank','thorny','fukuoka','fukushima','fukuda','fukui','shitake','shiitake','pussycat','pussywillow','retardant','badminton','sexual']::text[];
  toks text[] := array['ass','tit','cum','fag','fags','kys','kms','pedo','wtf','stfu','gtfo','mod','mods','staff','official','support','system','root','owner','ibo','null','undefined']::text[];
  reserved text[] := array['admin','moderator','superuser','scipa','oneinacomputer','mod','mods','staff','official','support','system','root','owner','ibo','null','undefined']::text[];
  raws text[] := array['1488']::text[];
  hate text := '(kill|hate|gas|hang|lynch|murder|shoot|burn|nuke|exterminate)(all|the|da)?(jews?|muslims?|blacks?|gays?|whites?|asians?|arabs?|mexicans?|christians?|women|girls|trans|immigrants?|refugees?|indians?|chinese)';
  low text; flat text; leet text; v1 text; v2 text; w text; tk text[]; allow2 text[];
begin
  if n is null or n = '' then return null; end if;
  low := translate(lower(regexp_replace(n, '([a-z])([A-Z])', '\1 \2', 'g')), 'àáâãäåāçćčèéêëēěìíîïīñńòóôõöøōùúûüūýÿžźżšśł', 'aaaaaaacccceeeeeeiiiiinnooooooouuuuuyyzzzssl');
  flat := regexp_replace(low, '[^a-z0-9]', '', 'g');
  foreach w in array raws loop if strpos(flat, w) > 0 then return 'bad'; end if; end loop;
  leet := translate(low, '0134578@$!|+9', 'oieastbasiitg');
  v1 := regexp_replace(leet, '[^a-z]', '', 'g');
  v2 := regexp_replace(v1, '(.)\1+', '\1', 'g');
  tk := regexp_split_to_array(low, '[^a-z]+') || regexp_split_to_array(leet, '[^a-z]+');
  foreach w in array toks loop
    if w = any(tk) then return case when w = any(reserved) then 'reserved' else 'bad' end; end if;
  end loop;
  select array_agg(regexp_replace(a, '(.)\1+', '\1', 'g')) into allow2 from unnest(allow) a;
  foreach w in array subs loop
    if public.name_banned_in(v1, w, allow)
       or (length(w) >= 4 and regexp_replace(w, '(.)\1+', '\1', 'g') = w and public.name_banned_in(v2, w, allow2)) then
      return case when w = any(reserved) then 'reserved' else 'bad' end;
    end if;
  end loop;
  if v1 ~ hate then return 'bad'; end if;
  return null;
end $fn$;

-- ============ 2. Profiles: one per account, readable and editable only by its owner ============
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  username text not null,
  display_name text,
  skin text not null default 'cs' check (skin ~ '^[a-z]{2,8}$'),
  hue smallint not null default 200 check (hue between 0 and 359),
  banner text not null default 'night' check (banner ~ '^[a-z]{2,12}$'),
  motto text not null default '' check (char_length(motto) <= 80),
  fav_subject text check (fav_subject is null or fav_subject ~ '^[a-z]{2,8}$'),
  show_special boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint username_format check (username ~ '^[A-Za-z][A-Za-z0-9_]{2,19}$' and position('__' in username) = 0),
  constraint display_name_length check (display_name is null or char_length(display_name) between 2 and 24)
);
create unique index if not exists profiles_username_lower on public.profiles (lower(username));

create or replace function public.profiles_guard() returns trigger
language plpgsql set search_path = '' as $fn$
begin
  if public.name_problem(new.username) is not null then
    raise exception 'name_not_allowed' using errcode = '23514', detail = 'username'; end if;
  if new.display_name is not null and public.name_problem(new.display_name) is not null then
    raise exception 'name_not_allowed' using errcode = '23514', detail = 'display_name'; end if;
  if public.name_problem(new.motto) is not null then
    raise exception 'name_not_allowed' using errcode = '23514', detail = 'motto'; end if;
  if new.motto ~ '[<>]' then raise exception 'motto_not_allowed' using errcode = '23514', detail = 'motto'; end if;
  new.updated_at := now();
  if tg_op = 'UPDATE' then new.id := old.id; new.created_at := old.created_at; end if;
  return new;
end $fn$;
drop trigger if exists profiles_guard on public.profiles;
create trigger profiles_guard before insert or update on public.profiles for each row execute function public.profiles_guard();

alter table public.profiles enable row level security;
drop policy if exists "own profile: read" on public.profiles;
drop policy if exists "own profile: create" on public.profiles;
drop policy if exists "own profile: update" on public.profiles;
create policy "own profile: read" on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy "own profile: create" on public.profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy "own profile: update" on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

-- is a username free and allowed? (answers yes/no without exposing anyone's profile)
create or replace function public.username_available(n text) returns boolean
language sql stable security definer set search_path = '' as $fn$
  select n ~ '^[A-Za-z][A-Za-z0-9_]{2,19}$' and position('__' in n) = 0 and public.name_problem(n) is null
     and not exists (select 1 from public.profiles p where lower(p.username) = lower(n) and p.id is distinct from auth.uid());
$fn$;
revoke all on function public.username_available(text) from public;
grant execute on function public.username_available(text) to anon, authenticated;

-- ============ 3. Saved games: daily dives, practice runs and Go to heaven ============
create table if not exists public.results (
  id bigint generated always as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  client_id text not null check (char_length(client_id) between 6 and 40),
  subject text not null check (subject ~ '^[a-z]{2,8}$'),
  mode text not null check (mode in ('daily','practice','heaven')),
  level text check (level in ('SL','HL')),
  scope text check (char_length(scope) <= 200),
  score integer not null default 0 check (score between 0 and 100000),
  prompts smallint not null default 0 check (prompts between 0 and 2000),
  gems smallint not null default 0 check (gems between 0 and 2000),
  bonus smallint not null default 0 check (bonus between 0 and 2000),
  bonus_asked smallint not null default 0 check (bonus_asked between 0 and 2000),
  reached text check (char_length(reached) <= 80),
  finished boolean not null default true,
  answers jsonb not null default '[]' check (jsonb_typeof(answers) = 'array' and jsonb_array_length(answers) <= 2000),
  extra jsonb not null default '{}' check (jsonb_typeof(extra) = 'object'),
  played_at timestamptz not null default now(),
  unique (user_id, client_id)
);
create index if not exists results_user_time on public.results (user_id, played_at desc);

create or replace function public.results_guard() returns trigger
language plpgsql set search_path = '' as $fn$
begin
  new.user_id := auth.uid();                                        -- always the signed-in player
  if new.played_at > now() then new.played_at := now(); end if;     -- no games from the future
  if pg_column_size(new.answers) > 200000 or pg_column_size(new.extra) > 4000 then
    raise exception 'result_too_large' using errcode = '23514'; end if;
  return new;
end $fn$;
drop trigger if exists results_guard on public.results;
create trigger results_guard before insert on public.results for each row execute function public.results_guard();

alter table public.results enable row level security;
drop policy if exists "own results: read" on public.results;
drop policy if exists "own results: add" on public.results;
drop policy if exists "own results: delete" on public.results;
create policy "own results: read" on public.results for select to authenticated using ((select auth.uid()) = user_id);
create policy "own results: add" on public.results for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "own results: delete" on public.results for delete to authenticated using ((select auth.uid()) = user_id);

-- ============ 4. The honey pot: estimated marks for uploaded IAs, EEs and HL essays ============
-- Only the marks are kept: the uploaded PDF is never stored. Rows are written by the "grade" Edge Function with the
-- project's secret key; players can read their own rows but not add, change or delete them, so the daily limit holds.
create table if not exists public.honey_grades (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  task text not null check (task ~ '^[a-z0-9]{2,12}$'),
  subject text not null check (subject ~ '^[a-z]{2,8}$'),
  level text check (level in ('SL','HL')),
  file_name text check (char_length(file_name) <= 80),
  status text not null default 'pending' check (status in ('pending','done')),
  total smallint check (total between 0 and 100),
  max smallint check (max between 1 and 100),
  grade text check (char_length(grade) <= 2),
  words integer check (words between 0 and 1000000),
  criteria jsonb check (criteria is null or (jsonb_typeof(criteria) = 'array' and jsonb_array_length(criteria) <= 12)),
  created_at timestamptz not null default now()
);
create index if not exists honey_grades_user_time on public.honey_grades (user_id, created_at desc);
alter table public.honey_grades enable row level security;
drop policy if exists "own honey grades: read" on public.honey_grades;
create policy "own honey grades: read" on public.honey_grades for select to authenticated using ((select auth.uid()) = user_id);

-- ============ 5. Delete my account (and everything saved with it) ============
create or replace function public.delete_me() returns void
language plpgsql security definer set search_path = '' as $fn$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  delete from auth.users where id = auth.uid();
end $fn$;
revoke all on function public.delete_me() from public;
grant execute on function public.delete_me() to authenticated;

-- ============ 6. Exactly what the website's public key may do ============
-- Needed when "Grant API access to new tables automatically" was left off, and a safe tightening when it was on.
grant usage on schema public to anon, authenticated;
revoke all on public.profiles, public.results, public.honey_grades from anon, authenticated;
grant select, insert, update on public.profiles to authenticated;
grant select, insert, delete on public.results to authenticated;
grant select on public.honey_grades to authenticated;
-- the grading Edge Function writes honey pot rows with the secret (service_role) key
do $do$ begin if exists (select 1 from pg_roles where rolname = 'service_role') then grant select, insert, update, delete on public.honey_grades to service_role; end if; end $do$;
grant execute on function public.name_problem(text), public.name_banned_in(text, text, text[]) to anon, authenticated;
